# tests/test_validator.pyimport pytestimport osimport sysimport yamlimport json# Добавляем корень проекта в путь импортаsys.path.insert(0, os.path.join(os.path.dirname(__file__), '..'))def test_validator_config_integrity():    """Проверяет, что конфиг валидатора существует и содержит конституционные слои"""    config_path = os.path.join('validator', 'config', 'validator_config.yaml')    assert os.path.exists(config_path), "❌ validator_config.yaml not found"    with open(config_path, encoding='utf-8') as f:        config = yaml.safe_load(f)    assert 'pipeline' in config    assert 'stages' in config  # ✅ Исправлено: stages находится на верхнем уровне    assert all(k in config['stages'] for k in ['CoreCheck', 'GammaCheck', 'LanguageCheck', 'MetaCheck'])def test_bridge_contract_constitutional_fixes():    """Проверяет, что в мосте применены все 3 конституционных исправления"""    bridge_path = os.path.join('contracts', 'bridges', 'm4_bridge_contract.yaml')    assert os.path.exists(bridge_path), "❌ m4_bridge_contract.yaml not found"    with open(bridge_path, encoding='utf-8') as f:        contract = yaml.safe_load(f)    spec = contract['BridgeSpec']    # Исправление 1: Z_R.5    assert spec['role_binding_protocol']['mechanism'] == "co-emergent_constitution"    # Исправление 2: Γ_Locality    assert "intersection(agent.causal_window, engine.causal_window)" in spec['TPN_Signal_Protocol']['scope']    # Исправление 3: A0_multi + friction    assert "1 - Γ_friction_k" in spec['A0_multi_X_Economic_Resolver']['formula']    assert "Z_Invariant_Rollback" in spec['A0_multi_X_Economic_Resolver']['fallback']def test_sandbox_report_generation():    """Проверяет, что sandbox генерирует валидный JSON-отчёт"""    from validator.ts_d_sandbox import DSandbox    sandbox = DSandbox(iterations=5) # Быстрый прогон для теста    report = sandbox.run_selfplay()    assert os.path.exists('ts_sandbox_report.json')    with open('ts_sandbox_report.json') as f:        data = json.load(f)    assert 'valid_bindings' in data    assert 'epsilon_friction_recommended' in data    assert data['valid_bindings'] >= 0def test_metacheck_pipeline_execution():    """Проверяет, что Layer 4 успешно читает отчёт и не падает с ошибками"""    from validator.ts_layer4_metacheck import run_metacheck    # Убеждаемся, что отчёт есть    if not os.path.exists('ts_sandbox_report.json'):        from validator.ts_d_sandbox import DSandbox        DSandbox(iterations=10).run_selfplay()    result = run_metacheck()    # Функция должна вернуть bool, а не выбросить исключение    assert isinstance(result, bool)